<?php
require 'db.php';
require_login();
$uid=(int)current_user()['user_id'];
$cartId=get_active_cart_id();
$items=[];$subtotal=0;
if($cartId){
    $s=$pdo->prepare('SELECT ci.cart_item_id,ci.product_id,ci.quantity,p.name,p.price,p.image,p.stock FROM cart_items ci JOIN products p ON p.product_id=ci.product_id WHERE ci.cart_id=?');
    $s->execute([$cartId]);$items=$s->fetchAll();
    foreach($items as $i)$subtotal+=(float)$i['price']*(int)$i['quantity'];
}
if(!$items){header('Location: cart.php');exit;}
$delivery=250;$total=$subtotal+$delivery;
$s=$pdo->prepare('SELECT u.name,u.email,u.contact,p.phone,p.shipping_address FROM users u LEFT JOIN profiles p ON p.user_id=u.user_id WHERE u.user_id=?');
$s->execute([$uid]);$profile=$s->fetch();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Secure Checkout | Ceylon Spice Hub</title><link rel="stylesheet" href="style.css"><style>.payment-option{display:flex;gap:12px;align-items:flex-start;border:1px solid #e7e3da;padding:16px;margin:10px 0;border-radius:10px;cursor:pointer}.payment-option input{margin-top:4px}.payment-option span{display:flex;flex-direction:column;gap:5px}.payment-option small{color:#68706b}.payhere-badge{display:inline-flex;align-items:center;gap:7px;margin-top:4px;font-size:11px;color:#0d5135;font-weight:700}.checkout-note{background:#f4f8f4;border:1px solid #dce9df;padding:12px 14px;margin:12px 0;font-size:12px;line-height:1.6;color:#526057}</style></head><body><header class="header"><div class="container nav-wrap"><a class="brand" href="index.php"><span>Ceylon</span><small>SPICE HUB</small></a><span class="secure-label">🔒 Secure Checkout</span></div></header><main class="checkout-page"><div class="container"><p class="eyebrow">CHECKOUT</p><h1 class="page-title">Complete your order</h1><div class="checkout-layout"><form class="checkout-form" action="place_order.php" method="post" id="checkoutForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Delivery Details</h2><div class="account-note">Logged in as <b><?=e($profile['name'])?></b> · <a href="profile.php">Edit profile</a></div><div class="form-grid"><label>Full Name<input name="customer_name" value="<?=e($profile['name'])?>" required></label><label>Email<input type="email" name="email" value="<?=e($profile['email'])?>" required></label><label>Phone Number<input name="contact" value="<?=e($profile['phone']??$profile['contact']??'')?>" required></label><label>City<input name="city" required placeholder="Colombo"></label></div><label>Delivery Address<textarea name="address" required rows="4"><?=e($profile['shipping_address']??'')?></textarea></label><h2>Payment Method</h2><label class="payment-option"><input type="radio" name="payment_method" value="Cash on Delivery" checked><span><b>💵 Cash on Delivery</b><small>Pay when your order arrives.</small></span></label><label class="payment-option"><input type="radio" name="payment_method" value="Bank Transfer"><span><b>🏦 Bank Transfer</b><small>Payment details can be provided after ordering.</small></span></label><label class="payment-option"><input type="radio" name="payment_method" value="PayHere"><span><b>💳 PayHere Online Payment</b><small>Securely pay online with PayHere using card and supported payment methods.</small><em class="payhere-badge">🔒 Secured by PayHere</em></span></label><div class="checkout-note">When you choose PayHere, your order is created as <b>Pending</b> and you are redirected to the PayHere secure payment page. The order becomes <b>Paid</b> only after the server verifies PayHere's payment notification.</div><button class="btn btn-primary submit-order" id="submitOrder">PLACE ORDER • <?=money($total)?></button></form><aside class="checkout-summary"><h2>Your Order</h2><?php foreach($items as $i):?><div class="order-mini"><img src="<?=e($i['image'])?>" alt=""><div><b><?=e($i['name'])?></b><small><?=$i['quantity']?> × <?=money((float)$i['price'])?></small></div></div><?php endforeach;?><hr><div><span>Subtotal</span><b><?=money($subtotal)?></b></div><div><span>Delivery</span><b><?=money($delivery)?></b></div><div class="total"><span>Total</span><b><?=money($total)?></b></div></aside></div></div></main><script>document.getElementById('checkoutForm').addEventListener('submit',function(){const b=document.getElementById('submitOrder');b.disabled=true;b.textContent='PROCESSING…';});</script></body></html>